window.ScripturaLexicons.BDAG_PART_0175 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-01\" data-source=\"BDAG\" data-search=\"ἱκετηρία, ας, ἡ substantivo feminino súplica; oração a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκετηρία, ας, ἡ</td><td>substantivo feminino</td><td>súplica; oração a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-02\" data-source=\"BDAG\" data-search=\"ἱκέτης, ου, ὁ substantivo masculino suplicante; quem implora misericórdia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκέτης, ου, ὁ</td><td>substantivo masculino</td><td>suplicante; quem implora misericórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-03\" data-source=\"BDAG\" data-search=\"ἰκμάς, άδος, ἡ substantivo feminino umidade; líquido exsudado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰκμάς, άδος, ἡ</td><td>substantivo feminino</td><td>umidade; líquido exsudado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-04\" data-source=\"BDAG\" data-search=\"Ἰκονιεύς, έως, ὁ substantivo masculino; gentílico habitante de Icônio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰκονιεύς, έως, ὁ</td><td>substantivo masculino; gentílico</td><td>habitante de Icônio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-05\" data-source=\"BDAG\" data-search=\"Ἰκόνιον, ου, τό topônimo neutro Icônio; cidade visitada por Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰκόνιον, ου, τό</td><td>topônimo neutro</td><td>Icônio; cidade visitada por Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-06\" data-source=\"BDAG\" data-search=\"ἰκτῖνος, ου, ὁ substantivo masculino gavião; milhafre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰκτῖνος, ου, ὁ</td><td>substantivo masculino</td><td>gavião; milhafre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-07\" data-source=\"BDAG\" data-search=\"ἱλαρός, ά, όν adjetivo alegre; contente; benevolente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλαρός, ά, όν</td><td>adjetivo</td><td>alegre; contente; benevolente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-08\" data-source=\"BDAG\" data-search=\"ἱλαρότης, ητος, ἡ substantivo feminino alegria; cordialidade; generosidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλαρότης, ητος, ἡ</td><td>substantivo feminino</td><td>alegria; cordialidade; generosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-09\" data-source=\"BDAG\" data-search=\"ἱλάσκομαι verbo depoente médio propiciar; aplacar; expiar pecados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλάσκομαι</td><td>verbo depoente médio</td><td>propiciar; aplacar; expiar pecados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-10\" data-source=\"BDAG\" data-search=\"ἱλασμός, οῦ, ὁ substantivo masculino expiação; sacrifício expiatório BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλασμός, οῦ, ὁ</td><td>substantivo masculino</td><td>expiação; sacrifício expiatório</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-11\" data-source=\"BDAG\" data-search=\"ἱλαστήριον, ου, τό substantivo neutro meio de expiação; lugar de propiciação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλαστήριον, ου, τό</td><td>substantivo neutro</td><td>meio de expiação; lugar de propiciação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-12\" data-source=\"BDAG\" data-search=\"ἱλατεύομαι verbo depoente médio ser benevolente para com alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱλατεύομαι</td><td>verbo depoente médio</td><td>ser benevolente para com alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-13\" data-source=\"BDAG\" data-search=\"ἵλεως, ων adjetivo bondoso; misericordioso; propício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἵλεως, ων</td><td>adjetivo</td><td>bondoso; misericordioso; propício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-14\" data-source=\"BDAG\" data-search=\"Ἰλλυρικόν, οῦ, τό topônimo neutro Ilírico; província romana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰλλυρικόν, οῦ, τό</td><td>topônimo neutro</td><td>Ilírico; província romana</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-15\" data-source=\"BDAG\" data-search=\"ἱμάς, άντος, ὁ substantivo masculino correia de couro; açoite BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱμάς, άντος, ὁ</td><td>substantivo masculino</td><td>correia de couro; açoite</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-16\" data-source=\"BDAG\" data-search=\"ἱματίζω verbo vestir; trajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱματίζω</td><td>verbo</td><td>vestir; trajar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-17\" data-source=\"BDAG\" data-search=\"ἱμάτιον, ου, τό substantivo neutro roupa; vestuário; manto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱμάτιον, ου, τό</td><td>substantivo neutro</td><td>roupa; vestuário; manto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-18\" data-source=\"BDAG\" data-search=\"ἱματισμός, οῦ, ὁ substantivo masculino vestuário; traje BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱματισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>vestuário; traje</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-19\" data-source=\"BDAG\" data-search=\"ἱμείρομαι verbo remissivo ver ὁμείρομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱμείρομαι</td><td>verbo remissivo</td><td>ver ὁμείρομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0175-20\" data-source=\"BDAG\" data-search=\"ἵνα conjunção para que; que; de modo que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἵνα</td><td>conjunção</td><td>para que; que; de modo que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0175-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετηρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(na realidade, o feminino do adjetivo <span class=\"greek\">ἱκετήριος</span>, subentendendo-se <span class=\"greek\">ἐλαία</span> ou <span class=\"greek\">ῥάβδος</span>: o ramo de oliveira era o sinal do suplicante. Como substantivo, «sinal de súplica» Ésquilo, Heródoto e outros) súplica (assim em Isócrates e outros; POslo 148, 12 [sécs. II/I a.C.]; 2 Macc 9:18; Fílon, Leg. ad Gai. 228) com <span class=\"greek\">δέησις</span> (Isócrates 8, 138 Blass variante de leitura; Jó 40:27; Fílon, Leg. ad Gai. 276). Como súplica dirigida a Deus, oração (Élio Aristides 49, 38 K.=25 p. 498 D.; Eliano, Fgm. 304; Sb 5103, 9; 11 [ver <span class=\"greek\">ἱκετεύω</span> acima]) com <span class=\"greek\">δέησις</span> (Polyb. 3, 112, 8 <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἱκετηρίαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δεήσεις</span>; Fílon, Cher. 47 variante de leitura) <span class=\"greek\">δεήσεις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἱκετηρίας</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δυνάμενον</span> <span class=\"greek\">σῴζειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">προσενέγκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>. CSpicq, RB 56, ’49, 549f.—DELG s.v. <span class=\"greek\">ἵκω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os três verbetes anteriores; Homero e outros; inscrições, LXX; TestAbr A 2 p. 78, 27 [Stone p. 4]; Fílon; Josefo, C. Ap. 2, 207) suplicante <span class=\"greek\">ἱκέται</span> <span class=\"greek\">γενόμενοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐλέους</span> <span class=\"greek\">αὐτοῦ</span> como suplicantes da misericórdia divina 1 Cl 9:1 (cf. Jos., Ant. 7, 361 <span class=\"greek\">ἱκέτης</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> e os preceitos délficos em SIG 1268, 24 <span class=\"greek\">ἱκέτας</span> <span class=\"greek\">ἐλέει</span>).—Ver também <span class=\"greek\">εὐλαβέομαι</span>.—DELG s.v. <span class=\"greek\">ἵκω</span>. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκμάς, άδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; LXX; Fílon, Op. M. 38. Exemplos de Josefo, Plutarco e Luciano, em Cadbury, Style 43) umidade: a umidade do solo, sem a qual as plantas não podem viver (Theophr., HP 6, 4, 8 <span class=\"greek\">ἰκμάδα</span> <span class=\"greek\">ἔχειν</span> em contraposição a <span class=\"greek\">ξηραίνεσθαι</span>; Jos., Ant. 3, 10; Jr 17:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:6</a>; Hs 8, 2, 7; 9. Dos líquidos exsudados pela carne em decomposição 1 Cl 25:3 (quanto ao uso médico da palavra, ver Hobart 57f).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰκονιεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">habitante de Icônio <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰκονιέων</span> <span class=\"greek\">πόλιν</span> AcPl Ox 6, 19 (=Aa I, 242, 1).—Pauly-W. IX/1, 990f.—Ver <span class=\"greek\">Ἰκόνιον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰκόνιον, ου, τό</h1><div class=\"entry-meta\"><span>topônimo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(sobre a grafia, ver B-D-F §42, 3; Rob. 197) Icônio (aproximadamente 140 km de Antioquia; segundo Xenofonte, An. 1, 2, 19 pertencente à Frígia, assim como em Plínio, Nat. Hist. 5, 41; Acta Justini 4; Estêvão de Bizâncio s.v.; mas Estrabão 12, 6, 1 a situa na Licaônia), visitada por Paulo em várias ocasiões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:51</a>; 14:1, 19, 21; 16:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:11</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">Ἰ</span>. AcPl Ant 13, 2 (=Aa I, 236, 6).—Ramsay, Bearing 53ff [Frígia], Cities 317–82; Bludau (s. <span class=\"greek\">Λύστρα</span>); AWikenhauser, Die Apostelgesch. 1921, 336f; VSchultze, Altchr. Städte u. Landschaften II 2, 1926; BHHW II 760; Conzelmann, Acts (Hermeneia) 107f.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκτῖνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(acusativo metaplástico <span class=\"greek\">ἰκτῖνα</span> [Cyranides p. 24, 8]) gavião, milhafre (Semônides, Teógnis, Heródoto, Xenofonte, Platão e outros), cuja carne era proibida aos israelitas como alimento (Lv 11:14; Dt 14:13) B 10:4.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Aristófanes, Xenofonte e posteriores; inscrições, papiros, LXX, En; TestJos 8:5; JosAs 23:10; EpArist; Philo; Jos., Bell. 6, 364, Ant. 18, 291; Tat. 26, 4 <span class=\"greek\">ἱλαρώτερον</span>) referente à disposição alegre: jovial, contente, feliz referido a coisas (Appian, Fgm. 7 <span class=\"greek\">βοὴ</span> <span class=\"greek\">ἱλαρά</span>; Aesop, Fab. 314 P.=Babr. 24 Cr.//L-P. <span class=\"greek\">ἱ</span>. <span class=\"greek\">κῶμοι</span>; Synes., Kingship 1 p. 1c <span class=\"greek\">λόγοι</span> <span class=\"greek\">ἱ</span>.; En 32:4 <span class=\"greek\">βότρυες</span> … <span class=\"greek\">ἱλαροὶ</span> <span class=\"greek\">λίαν</span>; Philo, Spec. Leg. 2, 48 <span class=\"greek\">ἱ</span>. <span class=\"greek\">βίος</span>) <span class=\"greek\">πάντα</span> <span class=\"greek\">ὁμαλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἱλαρά</span> tudo corre bem e de maneira alegre Hm 2:4; <span class=\"greek\">ὄψιν</span> … <span class=\"greek\">ἱλαρωτέραν</span> 3:1; <span class=\"greek\">μακροθυμία</span> 5, 2, 3; <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> … <span class=\"greek\">ἱλαρόν</span> 10, 3, 2; <span class=\"greek\">ἐντολαί</span> Hs 6, 1, 1; <span class=\"greek\">βοτάνας</span> <span class=\"greek\">ἱ</span>. 9, 1, 8; <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἱ</span>. 9, 10, 3; <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πολυτέλεια</span> <span class=\"greek\">καλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱλαρά</span> tal despesa é nobre e alegre Hs 1, 10; <span class=\"greek\">λειτουργία</span> <span class=\"greek\">καλὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱλαρά</span> um belo serviço realizado com alegria Hs 5, 3, 8; <span class=\"greek\">ἰδέα</span> … <span class=\"greek\">ἱλαρά</span> rosto alegre (do pastor) 6, 1, 6b.—De animais (Philostrat., Imag. 1, 15): ovelhas Hs 6, 1, 6a.—De seres humanos (TestJob 12:1; Diod S 4, 5, 3) v 1, 2, 3; 1, 4, 3; 3, 3, 1; 3, 9, 10 al. <span class=\"greek\">δότης</span> quem dá alegremente, de boa vontade (=sem relutância) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:7</a> (cf. Pv 22:8a). Contudo, alguns defendem aqui o sentido «bondoso, benevolente» (ver Nägeli 65f e Artemidoro 1, 5 <span class=\"greek\">θεοί</span>; POxy 1380, 127, a <span class=\"greek\">ἱλαρὰ</span> <span class=\"greek\">ὄψις</span> de Ísis; Philo, Spec. Leg. 4, 74 <span class=\"greek\">ἱ</span>. <span class=\"greek\">μεταδόσεις</span>=dádivas generosas).—DELG s.v. <span class=\"greek\">ἱλάσκομαι</span> 2. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαρότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἱλαρός</span>; Diod S 3, 17, 1; 4, 86, 6 Cornutus 24 p. 45, 11; Plut., Ages. 596 [2, 4]; Alciphron 3, 43; Vita Philonidis 21, 4 Crönert [SBBerlAk 1900, II 942ff]; PLond 1917, 4 [séc. IV d.C.] e PAnt 44, 6 [sécs. IV/V d.C.]; Pr 18:22; PsSol 4:5; 16:12; TestAbr A 20 p. 103, 16 [Stone p. 54]; TestNapht 9:2; Philo, Plant. 166) qualidade ou estado de quem está alegre, em contraposição a uma atitude que sugere constrangimento: alegria, contentamento, cordialidade, generosidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a>; Hm 5, 1, 2 (em contraste com <span class=\"greek\">ὀξυχολία</span>); 10, 3, 1 (em contraste com <span class=\"greek\">λύπηρος</span> <span class=\"greek\">ἀνήρ</span> «pessoa taciturna»); 4 (em oposição à «taciturnidade»); Hs 9, 15, 2 (personificada na última passagem).—DELG s.v. <span class=\"greek\">ἱλάσκομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλάσκομαι</h1><div class=\"entry-meta\"><span>verbo depoente médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os dois verbetes seguintes) depoente na voz média; futuro <span class=\"greek\">ἱλάσομαι</span> LXX; imperativo do 1º aoristo passivo <span class=\"greek\">ἱλάσθητι</span> (com sentido médio <span class=\"greek\">ἱλάσθην</span> LXX) (Homero e outros; inscrições; LXX [Thackeray 270f]; ver também Dodd e Hill, adiante).</p><p class=\"entry-text\">① fazer com que alguém se torne favoravelmente disposto, propiciar, aplacar, conciliar (Il. 1, 100 Apolo; Hdt. 5, 47, 2 um vencedor olímpico ofendido; 8, 112, 3 Temístocles; Estrabão 4, 4, 6 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; Cornutus 34 p. 73, 5; Heraclit. Sto. 16 p. 24, 9 <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἥλιον</span>; Apiano, Samn. 12 §6, Hann. 27 §115 <span class=\"greek\">θυσίαις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐχαῖς</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>; Herm. Wr. 1, 22; Fílon, Spec. Leg. 1, 116; Josefo, Ant. 6, 124 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἱ</span>.; 8, 112, C. Ap. 1, 308 <span class=\"greek\">ἱ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; SibOr 3:625628; ). Na voz passiva: a respeito de quem é invocado em oração: agir como alguém a quem se conseguiu aplacar, com ênfase, porém, na iniciativa daquele que assim procede: mostrar-se propício, misericordioso ou benevolente (4 Km 24:4; La 3:42; Da 9:19 Theod.) com dativo (de interesse, Esth 4:17h <span class=\"greek\">ἱλάσθητι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κλήρῳ</span> <span class=\"greek\">σου</span>; cf. também Sl 78:9) <span class=\"greek\">ἱλάσθητί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁμαρτωλῷ</span> (dativo de interesse) tem misericórdia de mim, que sou pecador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:13</a> (Sb 8511, 7 [inscrição de época imperial] <span class=\"greek\">ἵλαθί</span> <span class=\"greek\">μοι</span>, <span class=\"greek\">Μανδοῦλι</span> [uma divindade]); GJs 5:1 (duas vezes; na primeira ocorrência, talvez seguido de infinitivo, ver deStrycker 289 n. 2).—B-D-F §314.</p><p class=\"entry-text\">② eliminar os impedimentos que afastam a divindade, expiar, apagar; acerca de Cristo como sumo sacerdote <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱλάσκεσθαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> expiar os pecados do povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a> (assim em Mft. [NRSV «oferecer um sacrifício expiatório»] cf. SIG 1042, 15f [=IG II2, 1366; sécs. II/III d.C.] <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ὀφιλέτω</span> <span class=\"greek\">Μηνὶ</span> <span class=\"greek\">Τυράννῳ</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δύνηται</span> <span class=\"greek\">ἐξειλάσασθαι</span> ‘que fique em dívida para com Men Tirano por um pecado que não poderá expiar’ [cf. 1Km 3:14; sobre esta inscrição, ver New Docs 3, no. 6]; Ps 64:4 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀσεβείας</span> <span class=\"greek\">ἱ</span>.; Dssm., NB 52 [BS 225]; Breytenbach 98).—CDodd, JTS 32, ’31, 352–60; também Dodd 82–95 sobre <span class=\"greek\">ἱ</span>. e palavras relacionadas (contra Dodd: LMorris, ET 62, ’51, 227–33; RNicole, WTJ 17, ’55, 117–57; em apoio: NYoung, EvQ 55, ’83, 169–76); SLyonnet, Verbum Domini 37, ’59, 336–52, Sin, Redemption and Sacrifice, ’70, 120–66, 256–61; DHill, Gk. Words and Hebrew Mngs. ’67, 23–48; KGraystone, <span class=\"greek\">Ἱλάσκεσθαι</span> and Related Words in the LXX: NTS 27, ’81, 640–56; GHorsley, New Docs, 3, 25 (sobre Graystone e Hill); JFitzmyer, ‘Reconciliation’ in Pauline Theology, in: No Famine in the Land (McKenzie Festschr.) ’75, 155–77; JLunceford, An Historical and Exegetical Inquiry into the NT Meaning of the <span class=\"greek\">ἹΛΑΣΚΟΜΑΙ</span> Cognates, diss. Baylor ’79; CBreytenbach, Versöhnung ’89.—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλασμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver verbete anterior e o seguinte)</p><p class=\"entry-text\">① apaziguamento necessário por causa do pecado, expiação (<span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> Orph., Arg. 39; Plut., Fab. 18, 3; cf. Plut., Sol. 12, 5. Nesses casos ocorre o plural, provavelmente em referência aos atos individuais que devem ser expiados. Mas também no singular: Plut., Mor. 560d, Camill. 7, 5; Lev 25:9; Ps 129:4; Fílon, Leg. All. 3, 174) <span class=\"greek\">εἰς</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἐμοί</span> para minha expiação GJs 1:1; assim, talvez, um emprego abstrato em lugar do concreto, referindo-se a Jesus como o <span class=\"greek\">ἱ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:2</a>; 4:10. Entretanto, o sentido 2 tem sido muito adotado.</p><p class=\"entry-text\">② instrumento de aplacamento, sacrifício expiatório, oferta pelo pecado (Ez 44:27 <span class=\"greek\">προσοίσουσιν</span> <span class=\"greek\">ἱ</span>. cf. Nm 5:8; 2 Macc 3:33) ver acima.—Ver também a bibliografia citada no verbete <span class=\"greek\">ἱλάσκομαι</span>. DELG s.v. <span class=\"greek\">ἱλάσκομαι</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαστήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(substantivo neutro derivado de <span class=\"greek\">ἱλαστήριος</span>, <span class=\"greek\">ον</span> [PFay 337 I, 3ff—séc. II d.C.; 4 Macc 17:22; Jos., Ant. 16, 182]; ver os dois verbetes anteriores). Na literatura greco-romana, aquilo que serve de instrumento para recuperar o favor de uma divindade; concretamente, «meio de propiciação ou expiação, oferta destinada a obter expiação» (IKosPH, 81, 347 <span class=\"greek\">ὁ</span> <span class=\"greek\">δᾶμος</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τᾶς</span> <span class=\"greek\">Αὐτοκράτορος</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">Σεβαστοῦ</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἱλαστήριον</span>; ChronLind B 49 <span class=\"greek\">Ἀθάναι</span> <span class=\"greek\">ἱλατήριον</span>; Díon Crisóstomo 10 [11], 121. O significado é incerto em POxy 1985, 11).</p><p class=\"entry-text\">① meio de expiação, referente a Cristo, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">προέθετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἱλαστήριον</span> a quem Deus apresentou como meio de expiação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a> (assim na REB; cf. CBreytenbach, Versöhnung, ’89, 168 [ver adiante]; divergentemente GFitzer, TZ 22, ’66, 161–83 e NRSV «sacrifício expiatório»). A particularidade em relação ao uso greco-romano é que a iniciativa de remover os obstáculos à relação consigo mesmo parte de Deus. Nessa passagem <span class=\"greek\">ἱ</span>. também foi entendido como</p><p class=\"entry-text\">② lugar de propiciação (como Ezk 43:14, 17, 20; cf. também o «Gnadenstuhl» de Lutero e ver o comentário sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5</a> adiante). Sobre essa interpretação de <span class=\"greek\">ἱ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a> ver TManson, JTS 46, ’45, 1–10 (em oposição a ele, Breytenbach 167f.)—Ver também Dssm., ZNW 4, 1903, 193–212 (ver EncBibl III, 3027–35); PFiebig e GKlein ibid. 341–44; SFraenkel, ibid. 5, 1904, 257f; CBruston, ibid. 7, 1906, 77–81; GottfKittel, StKr 80, 1907, 217–33; EdaSMarco, Il piano divino della salute in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a>–26: diss. Rome ’37; VTaylor, ET 50, ’39, 295–300; GBarton, ATR 21, ’39, 91f; WDavies, Paul and Rabbinic Judaism2 ’55, 227–42; ELohse, Märtyrer u. Gottesknecht ’55; LMorris, NTS 2, ’55/56, 33–43; DWhiteley, JTS n.s. 8, ’57, 240–55; DBailey, Jesus as the Mercy Seat: diss. Cambridge ’99 (inscrição).—A LXX emprega <span class=\"greek\">ἱ</span>. para a tampa da arca da aliança, כ<span class=\"greek\">ַּ</span>פ<span class=\"greek\">ֹּ</span>ר<span class=\"greek\">ֶ</span>ת, sobre a qual era aspergido o sangue da oferta pelo pecado no Dia da Expiação (Ex 25:16ff al. Igualmente TestSol 21:2; Philo, Cher. 25, Fuga 100, Mos. 2, 95.—JStelma, Christus’ offer bij Pls [com Fílon] ’38). Assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5</a>, traduzido por «propiciatório»; sobre a história desse termo, ver OED s.v.—DELG s.v. <span class=\"greek\">ἱλάσκομαι</span> 1. M-M s.v. <span class=\"greek\">ἱλαστήριος</span>. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλατεύομαι</h1><div class=\"entry-meta\"><span>verbo depoente médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(sobre a formação, ver DELG s.v. <span class=\"greek\">ἱλάσκομαι</span>) 1º aoristo <span class=\"greek\">ἱλατευσάμην</span> (a forma ativa Jdth 16:15 variante de leitura; Da 9:19) ser benevolente <span class=\"greek\">τινί</span> para com alguém Hv 1, 2, 1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵλεως, ων</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(B-D-F §44, 1; W-S. §8, 8; Rdm. 62; Mlt. 240; Mlt-H. 121.—Homero e outros empregam a forma <span class=\"greek\">ἵλαος</span>; <span class=\"greek\">ἵλεως</span> é a forma ática. Também inscrições e papiros, LXX, JosAs, Philo, Joseph.) referente a uma disposição favorável, que implica vencer obstáculos contrários a uma relação: bondoso, misericordioso, na literatura mais ampla, predominantemente; nos textos aqui estudados e na LXX, sempre acerca de Deus (também Diodoro Sículo 4, 24, 4; Lucian, Pro Imag. 12; Oenomaus [época de Adriano], em Eusébio, PE 5, 19, 1 <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἵ</span>. <span class=\"greek\">ἔσται</span>; 6, 7, 42; M. Ant. 12, 36; Philo; Jos., Ant. 4, 222; 7, 290; SibOr 1, 161) <span class=\"greek\">ἵ</span>. <span class=\"greek\">ἔσομαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικίαις</span> <span class=\"greek\">αὐτῶν</span> serei misericordioso para com as iniquidades deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:12</a> (Jer 38:34). <span class=\"greek\">ἵλεώ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">τυγχάνειν</span> encontrar alguém misericordioso = alcançar misericórdia aos olhos de alguém (Herm. Wr. 5, 2; Philo, De Jos. 104) 1 Cl 61:2. <span class=\"greek\">ἵ</span>. <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τινί</span> ser benevolente ou indulgente para com alguém (Archilochus, Fgm. 75 <span class=\"greek\">Ἥφαιστε</span>, … <span class=\"greek\">μοὶ</span>, … <span class=\"greek\">ἵλαος</span> <span class=\"greek\">γενεῦ</span>; Sallust. 4 p. 10, 4; Num 14:19; Dt 21:8; 2 Macc 2:22) Hv 2, 2, 8. De modo absoluto: <span class=\"greek\">ἵ</span>. <span class=\"greek\">γενέσθαι</span> (Alciphron 4, 18, 17; UPZ 78, 24 [159 b.c.]; Ezk. Trag. vs. 124 [em Eusébio, PE 9, 29, 11]; TestSol 20:4) 1 Cl 2:3; 48:1; Hs 9, 23, 4.—<span class=\"greek\">ἵλεώς</span> <span class=\"greek\">σοι</span>, <span class=\"greek\">κύριε</span> (subentende-se <span class=\"greek\">εἴη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, como, de maneira semelhante, Herodas 4, 25; Plut., Mor. 983e <span class=\"greek\">ἵλεως</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἴη</span>) Deus te seja propício, Senhor; isto é, que Deus, em sua misericórdia, te poupe disso; de modo nenhum! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:22</a> (cf. IGR, 107, 10 <span class=\"greek\">ἵλεώς</span> <span class=\"greek\">σοι</span>=que [Serápis] te ajude; OGI 721, 10; Gen 43:23; 2 Km 20:20; 1 Ch 11:19; JosAs 6:4; ViDa 18 [p. 79, 8 Sch.].—Outra interpretação: PKatz, TLZ 82, ’57, 113f (ver também Kratylos 5, ’60, 159) e B-D-F §128, 5. Ver Rob. 395f; HMaehler, ZPE 4, ’69, 99f).—DELG s.v. <span class=\"greek\">ἱλάσκομαι</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰλλυρικόν, οῦ, τό</h1><div class=\"entry-meta\"><span>topônimo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(o adjetivo <span class=\"greek\">Ἰλλυρικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> em Apolônio de Rodes 4, 516; Estrabão) Ilírico, região situada do outro lado do mar Adriático em relação à Itália; na terminologia administrativa, compreendia a Dalmácia (Ilíria Superior) e a Panônia (Ilíria Inferior). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:19</a> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span>. é a única referência conservada à atividade missionária de Paulo nessa região. Entretanto, considerando a estreita ligação entre o Ilírico e a Macedônia (Apiano, Bell. Civ. 3, 63 §258; 4, 75 §317 <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰλλυρίδος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Μακεδονίᾳ</span>; 5, 145 §602) não há dificuldade em supor que Paulo tenha visitado o Ilírico a partir da Macedônia.—WWeber, Untersuchungen z. Gesch. des Kaisers Hadrianus 1907, 55.—Talvez Paulo também empregue essa expressão para indicar a imensa extensão do território que percorreu (como se dissesse: «de Dallas, no Texas, até Anchorage, no Alasca»)?—Ver <span class=\"greek\">Δαλματία</span>. Kl. Pauly II 1367–69. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱμάς, άντος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Hom. et al.; inscrições, papiros, LXX; Jos., Ant. 12, 192–94; Just., D. 131, 6) tira ou correia de couro, nas sandálias (X., An. 4, 5, 14; Menand., Fgm. 97, 3 Kö. [no. 109, 2 Kock]; Plut., Mor. 665b; Is 5:27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:27</a>. A interpretação de <span class=\"greek\">ὡς</span> <span class=\"greek\">προέτειναν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἱμᾶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:25</a> é discutida. Pode tratar-se de um dativo instrumental, «com as correias», utilizadas para amarrá-lo ao poste; é preferível, contudo, entendê-lo como dativo de finalidade, «para as correias», caso em que <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱμάντες</span>=açoites (Posidônio: 87 Fgm. 5 Jac.; POxy 1186, 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱμάντων</span> <span class=\"greek\">αἰκείαν</span>.—Antiphanes 74, 8, Demosth. 19, 197 e Artemidoro 1, 70 empregam o singular nesse sentido).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">particípio perfeito passivo <span class=\"greek\">ἱματισμένος</span> (ver os dois verbetes seguintes; PLond I, 24 recto, 14 p. 32 [163 a.C.]; BGU 1125, 8; PTebt 385, 15, e outros papiros) vestir, trajar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:35</a>.—DELG s.v. <span class=\"greek\">ἕννυμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱμάτιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete anterior e o seguinte; desde Hipônax 70, Hdt., Aristoph.+) originalmente «uma peça de vestuário»</p><p class=\"entry-text\">① roupa, vestuário, em geral, qualquer peça de roupa (PRyl 154, 8; PPetr II, 32, 18; PSI 94, 16; LXX) no singular, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21</a>; 5:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a>; 8:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:11f</a> (Ps 101:27); B 6:2 (Is 50:9) al. No plural, roupas (Philo, Leg. All. 3, 239) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:8</a> variante de leitura; 27:31, 35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:28</a>, 30; 9:3; 15:20, 24 al.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:25</a>; 23:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:23f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:15</a>. O plural nas passagens seguintes explica-se pelo fato de que cada uma de várias pessoas forneceu uma peça de roupa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:7</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:7</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:35</a>, 36 (sobre essas passagens, ver Plut., Cato Min. 764 [12, 1]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:39</a> (Paradoxogr. Vat. 26 Keller <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">ἐπιδεικνύναι</span>); Hs 9, 13, 5. <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱματίων</span> <span class=\"greek\">ἀλαζών</span> aquela que se orgulha de suas roupas AcPl Ha 2, 20.—<span class=\"greek\">ἀποθέσθαι</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱ</span>. tirar todas as próprias roupas MPol 13:2. <span class=\"greek\">περιαιρεῖσθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱ</span>. despir GJs 2:4. <span class=\"greek\">ἱ</span>. <span class=\"greek\">μαλακά</span> roupas macias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:25</a>. <span class=\"greek\">λευκά</span> roupas brancas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4f</a>, 18; 4:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a>. <span class=\"greek\">μέλανα</span> <span class=\"greek\">ἱ</span>. Hs 9, 15, 1; 3 (nesses casos <span class=\"greek\">ἱ</span>. pode ser omitido, como dizemos «vestido de branco» ou «de preto»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>; Hv 4, 2, 1. Cf. B-D-F §241, 7 e <span class=\"greek\">λευκός</span> 2, final). <span class=\"greek\">πενθικά</span> … <span class=\"greek\">νυμφικά</span> GJs 2:4 (Mel., P. 19, 132 <span class=\"greek\">ἱ</span>. <span class=\"greek\">πενθικόν</span>). <span class=\"greek\">σκυθροπότερα</span> roupas próprias de enlutados AcPl Ha 2, 16. Roupas estragadas pelas traças <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:2</a>. <span class=\"greek\">ἱ</span>. <span class=\"greek\">κατατρίβεται</span> desgastar-se AcPl Ha 2, 25; 9, 9 (texto restaurado). <span class=\"greek\">σύνθεσις</span> <span class=\"greek\">ἱματίων</span> Hs 6, 1, 5. <span class=\"greek\">ἔνδυσις</span> <span class=\"greek\">ἱματίων</span> ato de vestir roupas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:3</a>.</p><p class=\"entry-text\">② acerca da roupa exterior: manto, capa (Lucian, Alex. 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:20f</a>; 23:5 variante de leitura; 24:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:27</a>; 6:56; 10:50; 13:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:44</a>; 22:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:16</a>. Com <span class=\"greek\">χιτών</span>, a túnica de baixo (Diod S 4, 38, 1; Dio Chrys. 13 [7], 61; Diogenes, Ep. 30, 3; Diog. L. 6, 6; SIG 736, 17 [92 b.c.]; PEdg 11=Sb 6717, 9 [257 b.c.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:39</a>; D 1:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:40</a> (aqui a ordem é <span class=\"greek\">χιτ</span>. … <span class=\"greek\">ἱ</span>.; trata-se de uma demanda judicial, em que se aconselha o réu a entregar não apenas a indispensável <span class=\"greek\">χιτών</span> exigida pelo adversário, mas também o <span class=\"greek\">ἱ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a> (aqui a ordem é <span class=\"greek\">ἱ</span>. … <span class=\"greek\">χ</span>., sequência que sugere assalto na estrada, no qual o ladrão primeiro despoja a vítima da roupa exterior. Cf. UPZ 122, 14 [157 b.c.], o relato de um roubo: <span class=\"greek\">βουλόμενός</span> <span class=\"greek\">μου</span> <span class=\"greek\">περιελέσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span>. Também PLille 6, 9 <span class=\"greek\">ἐξέδυσαν</span> <span class=\"greek\">χιτῶνα</span> … <span class=\"greek\">ἱμάτιον</span>.—Mas Lucas talvez tivesse em mente Dt 24:10–13 [<span class=\"greek\">ἱ</span>. como penhor]. Por não retaliar, o devedor evidencia o descaramento do credor: FDanker, Jesus and the New Age, ’88, 145). <span class=\"greek\">ἱ</span>. <span class=\"greek\">περιβάλλειν</span>, <span class=\"greek\">περιβάλλεσθαι</span> (PFay 12, 19 [c. 103 b.c.]; Gen 28:20; 1 Km 28:8 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:13</a>. A roupa exterior era deixada de lado para liberar os braços <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58</a>; 22:20; assim, talvez também no v. 23. Era rasgada em sinal de luto (frequentemente na LXX) 14:14, e retirada de quem seria açoitado 16:22.</p><p class=\"entry-text\">③ Certas passagens situam-se entre 1 e 2; falam de <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span>, mas referem-se apenas a uma pessoa, que evidentemente faz algo com uma única peça de roupa exterior (Mussies 83): <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">διέρρηξεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:65</a> (cf. Gen 37:29, 34; Josh 7:6; Jdth 14:16 al.). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:4</a>, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:6</a>.—B 3:4 <span class=\"greek\">ἱμάτια</span> é uma leitura incerta: variante de leitura <span class=\"greek\">ἰάματα</span>; trata-se de citação de Is 58:8 (ver ali as variantes, ed. JZiegler).—Dalman, Arbeit V ’37. BHHW II 962–65. B. 395; 416. DELG s.v. <span class=\"greek\">ἕννυμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱματισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os dois verbetes anteriores; Theophr., Char. 23, 8; Polyb. 6, 15, 4; Diod S 17, 94, 2; Plut., Alex. 39, 10; SIG 999, 5; 1015, 36; PHib 54, 16 [c. 245 a.C.]; PTebt 381, 13; 384, 19; LXX; JosAs 2:7; Philo, Migr. Abr. 105) roupas, vestuário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a> (Ps 21:19); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:33</a>; D 13:7; B 6:6 (Ps 21:19); Hs 9, 13, 3. <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἔνδοξος</span> roupas finas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:25</a>. <span class=\"greek\">ἱ</span>. <span class=\"greek\">πολυτελής</span> vestuário luxuoso (Pel.—Leg. p. 4, 8; cf. Plut., Mor. 229a <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">πολυτελῆ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>. <span class=\"greek\">ἱ</span>. <span class=\"greek\">λαμπρότατος</span> vestuário resplandecente Hv 1, 2, 2. Roupas brancas (Aeneas Tact. 1488 <span class=\"greek\">ἱ</span>. <span class=\"greek\">λευκός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:29</a>; Hs 8, 2, 3f.—DELG s.v. <span class=\"greek\">ἕννυμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱμείρομαι</h1><div class=\"entry-meta\"><span>verbo remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">ὁμείρομαι</span> e Frisk s.v. <span class=\"greek\">ἵμερος</span>. M-M. s.v. <span class=\"greek\">ἱμείρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0175-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵνα</h1><div class=\"entry-meta\"><span>conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Hom.+) conjunção cujo emprego aumentou consideravelmente no grego helenístico em comparação com os períodos anteriores, porque passou a ser utilizada como perífrase em lugar do infinitivo e do imperativo. B-D-F §369; 379; 388–94 al.; Mlt. index; Rob. index.</p><p class=\"entry-text\">① partícula que indica propósito, intenção ou finalidade: «a fim de que», «para que», em sentido final</p><p class=\"entry-text\">ⓐ com subjuntivo, não apenas após um tempo primário, mas também, de acordo com o uso helenístico, após um tempo secundário (B-D-F §369, 1; Rob. 983; Mlt-Turner 100–102; JKnuenz, De enuntiatis Graecorum finalibus 1913, 15ff):</p><p class=\"entry-text\"><span class=\"greek\">α</span>. após um tempo presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a>; 7:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:34</a>; 8:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:15</a>; 5:34; 6:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:25</a> (Ps 15:8); 16:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:11</a>; 3:19; 11:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a>; 6:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:3</a> e frequentemente</p><p class=\"entry-text\"><span class=\"greek\">β</span>. após um perfeito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:22</a>; 21:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:23</a>, 36; 6:38; 12:40, 46; 14:29; 16:1, 4; 17:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:22b</a> al.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. após imperativo presente ou aoristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:1</a>; 14:15; 17:27; 23:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:15</a>; 5:14; 10:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>; 11:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a>. Igualmente após o subjuntivo exortativo na primeira pessoa do plural <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. após um futuro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:4</a>; 18:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:20</a>; 14:3, 13, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. após um tempo secundário: imperfeito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:2</a>; 6:41; 8:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:7</a>; 18:15 al.—Mais-que-perfeito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:8</a>.—Aoristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:14</a>; 11:28; 14:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:4</a>, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:32</a>; 12:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a>; 11:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:5</a>.</p><p class=\"entry-text\">ⓑ com futuro do indicativo (LXX, por exemplo, Sus 28; En 15:5; TestSol 13:7; SIG 888, 87ff; OGI 665, 35; POxy 299; 1071, 5 <span class=\"greek\">ἵνα</span> <span class=\"greek\">ποιήσουσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πέμψουσιν</span>; Gen 16:2 [Swete; ARahlfs, Genesis 1926 variante de leitura] al.; Just., D. 115, 6), ao lado do qual os manuscritos geralmente apresentam o subjuntivo aoristo (B-D-F §369, 2; Rob. 984; Mlt-Turner 100) <span class=\"greek\">ἵνα</span> <span class=\"greek\">σταυρώσουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:20</a> variante de leitura <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐρεῖ</span> <span class=\"greek\">σοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:10</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">δώσουσιν</span> 20:10. <span class=\"greek\">ἵνα</span> <span class=\"greek\">θεωρήσουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:3</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">δώσει</span> 17:2 variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:3</a>. <span class=\"greek\">ἐπισκιάσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a> variante de leitura; <span class=\"greek\">ξυρήσονται</span> 21:24. <span class=\"greek\">κερδανῶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:21</a> variante de leitura; <span class=\"greek\">καυθήσομαι</span> 13:3 variante de leitura <span class=\"greek\">καταδουλώσουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:4</a>. <span class=\"greek\">κερδηθήσονται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:1</a>. <span class=\"greek\">ἵνα</span> … <span class=\"greek\">δηλώσεις</span> Hv 3, 8, 10. O futuro do indicativo também se emprega com frequência quando <span class=\"greek\">ἵνα</span> não possui sentido final, especialmente em Rv: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:18</a> (<span class=\"greek\">ἵνα</span> como resposta, assim como em Epict. 4, 1, 99); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:4</a>, 11; 9:4, 5, 20; 13:12; 14:13; 22:14. Às vezes o futuro do indicativo e o subjuntivo aoristo ocorrem na mesma frase <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:9</a>; cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:10f</a> variante de leitura (sobre essa alternância, ver Reinhold 106; JVogeser, Zur Sprache d. griech. Heiligenlegenden, diss. Munich 1907, 34f; Knuenz, op. cit. 23ff; 39; Dio Chrys. 26 [43], 7 <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρῶ</span> … <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ἕξουσιν</span>; POxy 1068, 5 <span class=\"greek\">ἵνα</span> <span class=\"greek\">διαπέμψεται</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">δυνηθῶ</span> … ).—Sobre a alternância do subjuntivo presente e do futuro do indicativo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:8</a> ver GLee, Biblica 51, ’70, 239f.</p><p class=\"entry-text\">ⓒ <span class=\"greek\">ἵνα</span> aparece com o presente do indicativo apenas em passagens nas quais o subjuntivo também é atestado nos manuscritos; a ocorrência do indicativo provavelmente se deve à corrupção textual (B-D-F §369, 6; Rob. 984f; Mlt-Turner 100f. Mas veja-se o exemplo inequívoco em PAnt III, 188, 15: <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span> <span class=\"greek\">ἐσμεν</span>, e cf. BGU 1081, 3 <span class=\"greek\">ἐχάρην</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἀσπάζομαι</span>; TestNapht 8:2; PassPtPl 60 [Aa I, 170, 8] <span class=\"greek\">ἵνα</span> <span class=\"greek\">κατευθύνει</span>; AcPtPl 58 [Aa I, 203, 17]; AcPlTh 11 [Aa I, 243, 11 variante de leitura]). <span class=\"greek\">φυσιοῦσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a> e <span class=\"greek\">ζηλοῦτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:17</a> podem ser formas do subjuntivo (B-D-F §91; Rob. 984). Entretanto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a> variante de leitura <span class=\"greek\">διώκονται</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:4</a> variante de leitura <span class=\"greek\">σωφρονίζουσιν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:20</a> variante de leitura <span class=\"greek\">θαυμάζετε</span>; 17:3 variante de leitura <span class=\"greek\">γινώσκουσιν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:20</a> variante de leitura <span class=\"greek\">γινώσκομεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:6</a> variante de leitura <span class=\"greek\">τρέφουσιν</span>; 13:17 variante de leitura <span class=\"greek\">δύναται</span>; <span class=\"greek\">ἵνα</span> <span class=\"greek\">σύνετε</span> B 6:5 variante de leitura (no texto <span class=\"greek\">συνιῆτε</span>; variante de leitura <span class=\"greek\">συνῆτε</span>); <span class=\"greek\">ἵνα</span> … <span class=\"greek\">ᾂδετε</span> IEph 4:2 (Lghtf. <span class=\"greek\">ᾂδητε</span>); <span class=\"greek\">μετέχετε</span> ibid. (variante de leitura <span class=\"greek\">μετέχητε</span>). <span class=\"greek\">διατάσσομαι</span> ITr 3:3 (variante de leitura <span class=\"greek\">διατάσσωμαι</span>). <span class=\"greek\">βλασφημεῖται</span> 8:2 variante de leitura</p><p class=\"entry-text\">ⓓ O optativo após <span class=\"greek\">ἵνα</span> não é empregado na literatura aqui estudada (B-D-F §369, 1; 386, 3; Rob. 983). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:2</a> variante de leitura <span class=\"greek\">ἵνα</span> <span class=\"greek\">λάβοι</span> (em lugar de <span class=\"greek\">λάβῃ</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:17</a> <span class=\"greek\">ἵνα</span> <span class=\"greek\">δῴη</span> (variante de leitura <span class=\"greek\">δῷ</span>) é certamente subjuntivo, e <span class=\"greek\">δώῃ</span> é a leitura correta (B-D-F §95, 2; Mlt. 196f). Igualmente <span class=\"greek\">ἵνα</span> <span class=\"greek\">παραδοῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:2</a>.</p><p class=\"entry-text\">ⓔ depois de um demonstrativo (Epict. 2, 5, 16 <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> … <span class=\"greek\">ἵνα</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span> para isto (a saber), para que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:9</a>; 4:6; B 5:1, 11; 14:5. <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span> precisamente para esta finalidade: para que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span> por esta razão … para que (Himerius, Or. 14, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:10</a>; Phlm 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>; a oração introduzida por <span class=\"greek\">ἵνα</span> também pode preceder <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:31</a>. <span class=\"greek\">τούτου</span> <span class=\"greek\">χάριν</span> … <span class=\"greek\">ἵνα</span> por esta razão … para que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a>.</p><p class=\"entry-text\">ⓕ <span class=\"greek\">ἵνα</span> com a expressão subentendida «gostaria de dizer isto» também se encontra no grego mais antigo (Soph. Ph. 989) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:10</a> (B-D-F §470, 3. Com interpretação diferente [como um imperativo virtual] DSharp, ET 38, 1927, 427f). O elemento que precisa ser subentendido aparece antes em <span class=\"greek\">ἵνα</span> <span class=\"greek\">δείξῃ</span> (ele disse isso), a fim de mostrar B 7:5.—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:13</a>.</p><p class=\"entry-text\">② partícula introdutora de oração objetiva, «que». Com muita frequência o sentido final se enfraquece consideravelmente ou desaparece por completo. Nesse caso, a construção com <span class=\"greek\">ἵνα</span> substitui um infinitivo que complementa um verbo, ou a construção de acusativo com infinitivo. (cf. Od. 3, 327 e um documento espúrio em Demosth. 18, 155. Posteriormente, muito frequente, também em inscrições e papiros [Rdm.2 191ff]; LXX).</p><p class=\"entry-text\">ⓐ após verbos com o sentido de</p><p class=\"entry-text\"><span class=\"greek\">α</span>. «querer, desejar, esforçar-se» (PGiss 17, 5 [séc. II d.C.] <span class=\"greek\">ἠγωνίασα</span> … <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀκούσω</span>; BGU 1081, 3 <span class=\"greek\">ἐχάρην</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἀσπάζομαι</span>) <span class=\"greek\">θέλειν</span> <span class=\"greek\">ἵνα</span> (TestAbr A 19, 101, 9 [Stone p. 50]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:30</a>; 10:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:5</a>. <span class=\"greek\">βουλεύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:53</a>; 12:10. <span class=\"greek\">συμβουλεύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:4</a>. <span class=\"greek\">συντίθεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:22</a>. <span class=\"greek\">ἀγαλλιᾶσθαι</span> esforçar-se alegremente por 8:56 (ver <span class=\"greek\">ἀγαλλιάω</span>). <span class=\"greek\">ζητεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:2</a>; 14:12; AcPlCor 2:8. <span class=\"greek\">ζηλοῦν</span> 14:1. <span class=\"greek\">εὔχεσθαι</span> «desejar» IPhld 6:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. «ter cuidado, envergonhar-se, temer» <span class=\"greek\">φυλάσσεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:17</a>. <span class=\"greek\">προσέχειν</span> ter o cuidado de que B 16:8. <span class=\"greek\">βλέπειν</span> procurar assegurar que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:10</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. «pedir, exigir»: <span class=\"greek\">δεῖσθαι</span> pedir (Dionísio Hal. 4, 12, 1; Lucian, Dom. 9; Jos., Ant. 6, 321; 12, 125 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:40</a>; 21:36; 22:32; B 12:7; Pol 6:2; Hv 3, 1, 2; Hs 5, 4, 1. <span class=\"greek\">ἐρωτᾶν</span> solicitar (ver <span class=\"greek\">ἐρωτάω</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:36</a>; 16:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:47</a>; 17:15 al. (JEarwaker, ET 75, ’64, 316f interpreta assim o terceiro <span class=\"greek\">ἵνα</span> em 17:21). <span class=\"greek\">παρακαλεῖν</span> pedir, exortar (EpArist 318; 321, Jos., Ant. 14, 168) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:18</a>; 6:56; 7:32; 8:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a> al. <span class=\"greek\">αἰτεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:9</a> (Just., D. 30, 2 <span class=\"greek\">αἰτοῦμεν</span>). <span class=\"greek\">προσεύχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:20</a>; 26:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:13</a> al. <span class=\"greek\">εὔχεσθαι</span> orar (ver <span class=\"greek\">εὔχομαι</span> 1 end) Hs 5, 2, 10. <span class=\"greek\">εὐχαριστεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:16f</a>. <span class=\"greek\">ἀξιοῦν</span> exigir, solicitar (CIG 4892, 13 [séc. III d.C.]; Jos., Ant. 14, 22) Hv 4, 1, 3. <span class=\"greek\">καταξιοῦν</span> ISm 11:1; IPol 7:2.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. «convocar, incentivar, ordenar» (Epict, 4, 11, 29; 1 Esdr 8:19; EpArist 46) <span class=\"greek\">ἀπαγγέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:10</a>. <span class=\"greek\">παραγγέλλειν</span> (CIG 4957, 48 [68 d.C.], texto restaurado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>. <span class=\"greek\">διαμαρτύρεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:21</a>. <span class=\"greek\">ἐντέλλεσθαι</span> (Jos., Ant. 7, 356) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:17</a>. <span class=\"greek\">κηρύσσειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:12</a>. <span class=\"greek\">διαστέλλεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:43</a>; 7:36; 9:9. <span class=\"greek\">ἐπιτιμᾶν</span> advertir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:20</a>; 20:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:30</a>; 10:48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>. <span class=\"greek\">ἐξορκίζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a>. <span class=\"greek\">ὁρκίζειν</span> Hs 9, 10, 5. <span class=\"greek\">λέγειν</span> ordenar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:3</a>; 20:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:9</a>; 9:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:3</a>; 10:40; Hv 2, 2, 6. <span class=\"greek\">γράφειν</span> escrever (Jos., Ant. 11, 7; 127) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12</a>; 12:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:28</a>. <span class=\"greek\">ἀποστέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:36</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. «causar, produzir» <span class=\"greek\">πείθειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:20</a>. <span class=\"greek\">ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:9</a>; 13:16. <span class=\"greek\">τιθέναι</span> designar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:16</a>. <span class=\"greek\">ἀγγαρεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:21</a>.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. «permitir, conceder» <span class=\"greek\">ἀφιέναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:16</a>. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:7</a> ver CBarrett, The Gospel According to St. John2, ’78, 413–14. <span class=\"greek\">διδόναι</span> 10:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:5</a>.</p><p class=\"entry-text\"><span class=\"greek\">η</span>. <span class=\"greek\">συνευδοκεῖν</span> Hs 5, 2, 8.</p><p class=\"entry-text\">ⓑ após expressões impessoais: <span class=\"greek\">ἀρκετόν</span> (<span class=\"greek\">ἐστι</span>) é suficiente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:25</a>. <span class=\"greek\">λυσιτελεῖ</span> (<span class=\"greek\">εἰ</span> … <span class=\"greek\">ἢ</span> <span class=\"greek\">ἵνα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a>. <span class=\"greek\">συμφέρει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29f</a>; 18:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:50</a>. <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐλάχιστόν</span> <span class=\"greek\">ἐστιν</span> para mim é questão de pouca importância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:3</a>. <span class=\"greek\">ἔδει</span> B 5:13. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">λείπει</span> Hv 3, 1, 9.</p><p class=\"entry-text\">ⓒ após substantivos e adjetivos, especialmente quando integram expressões fixas:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:25</a>; 16:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:27</a>. <span class=\"greek\">ἔστιν</span> <span class=\"greek\">συνήθεια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:39</a>. <span class=\"greek\">θέλημά</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:12b</a>. <span class=\"greek\">βουλὴ</span> <span class=\"greek\">ἐγένετο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:42</a>. <span class=\"greek\">ἐντολή</span> (cf. Polyb. 36, 17, 10 <span class=\"greek\">νόμος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:12</a>; 11:57; 13:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a>; 2J 6. <span class=\"greek\">δέησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:19</a>. <span class=\"greek\">ἐξουσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:19</a>. <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">βρῶμά</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:34</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθός</span>; <span class=\"greek\">ἵνα</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:18</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ἱκανός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ἄξιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:27</a>; cf. Hs 9, 28, 5. Ver B-D-F §379; Rob. 996.</p><p class=\"entry-text\">ⓓ após substantivos que indicam tempo: <span class=\"greek\">χρόνον</span> <span class=\"greek\">διδόναι</span>, <span class=\"greek\">ἵνα</span> dar tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:21</a>. <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> chega a hora (Aesop, Fab. 242 H. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span>, <span class=\"greek\">ἵνα</span>=o dia em que) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:23</a>; 13:1; 16:2, 32. Ver B-D-F §382, 1; 393.</p><p class=\"entry-text\">ⓔ <span class=\"greek\">ἵνα</span> também pode substituir o infinitivo explicativo após um demonstrativo (B-D-F §394; Rdm.2 192.—Wsd 13:9; Just., D. 14, 2 <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμβολον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> …) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:28</a>. <span class=\"greek\">πόθεν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔλθῃ</span> (em lugar de <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐλθεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτλ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:43</a> (cf. GJs 12:2). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">προσεύχομαι</span> <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>. cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:18</a>. Trata-se de um uso frequente em João: <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">πιστεύητε</span> (em lugar de <span class=\"greek\">τὸ</span> <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">ὑμᾶς</span>) 6:29; cf. vs. 50. <span class=\"greek\">μείζονα</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἵνα</span> … <span class=\"greek\">θῇ</span> (em lugar de <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεῖναι</span>) 15:13; cf. 3J 4.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:39</a>; 17:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:11</a>, 23; 4:21; 5:3; 2J 6a. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>: <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ἐδοξάσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἵνα</span> … <span class=\"greek\">φέρητε</span> (em lugar de <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φέρειν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐδοξάσθη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:17</a>.—Ver também Hs 9, 28, 4, e <span class=\"greek\">ποταπὴν</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:1</a>.</p><p class=\"entry-text\">ⓕ <span class=\"greek\">ἵνα</span> é empregado elipticamente <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἵνα</span> mas isso aconteceu para que, caso em que o verbo subentendido deve ser inferido do contexto (Epict. 1, 12, 17): <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἵνα</span> <span class=\"greek\">μαρτυρήσῃ</span> (subentende-se <span class=\"greek\">ἦλθεν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:8</a>. <span class=\"greek\">ἀλλ</span>’ (<span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἀπόκρυφον</span>) <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔλθῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φανερόν</span> mas estava oculto para que viesse a ser revelado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:22</a> (mas cf. CCadoux, JTS 42, ’41, 169 n. 3). <span class=\"greek\">ἀλλ</span>’ (<span class=\"greek\">κρατεῖτέ</span> <span class=\"greek\">με</span>) <span class=\"greek\">ἵνα</span> <span class=\"greek\">πληρωθῶσιν</span> mas vós me estais prendendo, para que 14:49. <span class=\"greek\">ἀλλ</span>’ (<span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τυφλὸς</span>) <span class=\"greek\">ἵνα</span> <span class=\"greek\">φανερωθῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:3</a>. <span class=\"greek\">ἀλλ</span>’ (<span class=\"greek\">ἀποθνῄσκει</span>) <span class=\"greek\">ἵνα</span> … <span class=\"greek\">συναγάγῃ</span> 11:52.—13:18; Hv 3, 8, 10 (cf. 1b acima).</p><p class=\"entry-text\">ⓖ <span class=\"greek\">ἵνα</span> com subjuntivo como perífrase do imperativo (B-D-F §387, 3; Mlt. 178; 210f; 248; Rob. 994; Mlt-Turner 94f; FSlotty, D. Gebr. des Konj. u. Opt. in d. griech. Dialekten I 1915, 35; CCadoux, The Impv. Use of <span class=\"greek\">ἵνα</span> in the NT: JTS 42, ’41, 165–73; em resposta, HMeecham, JTS 43, ’42, 179f, também ET 52, ’40/41, 437; AGeorge, JTS 45, ’44, 56–60. Goodsp., Probs. 57f.—Soph., Oed. Col. 155; Epict. 4, 1, 41, Enchir. 17; PTebt 408, 17 [3 d.C.]; BGU 1079, 20; PFay 112, 12; POxy 299, 5 <span class=\"greek\">ἵν</span>’ <span class=\"greek\">εἰδῇς</span> «saiba»; PGM 4, 2135; Tob 8:12 BA; 2 Macc 1:9. <span class=\"greek\">ἵνα</span> <span class=\"greek\">πρὶν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἴδητε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπώλειαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">υἱῶν</span> «antes desses acontecimentos, vereis a destruição de vossos filhos» En 14:6. <span class=\"greek\">κύριε</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">γινώσκῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σὸν</span> <span class=\"greek\">κράτος</span> <span class=\"greek\">ὅτι</span> «Senhor, que em tua majestade saibas que…» TestAbr A 4 p. 80, 35f [Stone pp. 8 e 10]). <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπιθῇς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">αὐτῇ</span> por favor, impõe as mãos sobre ela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:23</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">φοβῆται</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄνδρα</span> a esposa deve respeitar o marido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:33</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>; 16:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀναπαήσονται</span> que descansem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:13</a>. Com <span class=\"greek\">θέλω</span>: <span class=\"greek\">θέλω</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">δῷς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:25</a> (=<span class=\"greek\">δός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:8</a>.).—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:10</a>, ver 1f acima.</p><p class=\"entry-text\">ⓗ <span class=\"greek\">ἵνα</span> sem verbo finito, o qual pode ser suprido a partir do contexto (Epict. 3, 23, 4 <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἄνθρωπος</span>, isto é, <span class=\"greek\">ἐργάζῃ</span>) <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>, <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">περιτομήν</span> (isto é, <span class=\"greek\">εὐαγγελιζώμεθα</span> e <span class=\"greek\">εὐαγγελίζωνται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:9</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">χάριν</span> (<span class=\"greek\">γένηται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:16</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">ἄνεσις</span> (<span class=\"greek\">γένηται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:13</a>. <span class=\"greek\">ἵνα</span> (<span class=\"greek\">γένηται</span>) <span class=\"greek\">καθὼς</span> <span class=\"greek\">γέγραπται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:31</a> (B-D-F §481; Rob. 1202f).</p><p class=\"entry-text\">③ partícula que substitui o infinitivo de resultado: «de modo que» (uso «ecbático» ou consecutivo de <span class=\"greek\">ἵνα</span>: B-D-F §391, 5; Mlt. 206–9; Rob. 997–99 e em SCase, Studies in Early Christianity [Porter-Bacon Festschr.] 1928, 51–57; EBlakeney, ET 53, ’41/42, 377f, sugerindo que o resultado é considerado provável, mas não efetivo. Essa distinção, porém, nem sempre é rigorosamente observada. Cf. Epict. 1, 24, 3; 25, 15; 27, 8 al.; 2, 2, 16 <span class=\"greek\">οὕτω</span> <span class=\"greek\">μωρὸς</span> <span class=\"greek\">ἦν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἴδῃ</span>; Vett. Val. 185, 31; 186, 17; 292, 20; Jos., Bell. 6, 107; Just., D. 112, 5; PLond III, 964, 13 p. 212 [sécs. II/III d.C.]. Muitos exemplos em AJannaris, An Historical Greek Grammar 1897 §1758 e 1951) <span class=\"greek\">ἦν</span> <span class=\"greek\">παρακεκαλυμμένον</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">αἴσθωνται</span> <span class=\"greek\">αὐτό</span> isso lhes foi ocultado, de modo que não o compreendessem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:45</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">ἥμαρτεν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">τυφλὸς</span> <span class=\"greek\">γεννηθῇ</span>; Quem pecou, de modo que ele nascesse cego? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>; 13:13; Hs 7:2; 9, 1, 10.—Em muitos casos, finalidade e resultado não podem ser claramente distinguidos, razão pela qual <span class=\"greek\">ἵνα</span> é empregado para o resultado que decorre da intenção do sujeito ou de Deus. Como no pensamento semítico e greco-romano, finalidade e resultado são idênticos nas declarações da vontade divina (Ps.-Callisth. 2, 16, 10 o poder do rei persa está sendo derrubado pela divindade <span class=\"greek\">ἵνα</span> <span class=\"greek\">Δαρεῖος</span> … <span class=\"greek\">φυγὰς</span> <span class=\"greek\">γενόμενος</span> <span class=\"greek\">κτλ</span>. Aqui <span class=\"greek\">ἵνα</span> significa tanto «a fim de que» quanto «de modo que»): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a>; 12:40; 19:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a>; 5:20; 7:13; 8:17; 11:31f al. (ESutcliffe, Effect or Purpose, Biblica 35, ’54, 320–27). A fórmula <span class=\"greek\">ἵνα</span> <span class=\"greek\">πληρωθῇ</span> deve ser entendida desse modo, pois o cumprimento ocorre segundo o plano divino de salvação: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:22</a>; 2:15; 4:14; 12:17; 21:4; 26:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:38</a>; 17:12; 19:24, 36.—O <span class=\"greek\">ἵνα</span> de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:12</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:10</a>, tão controvertido, provavelmente deve ser entendido como final (com AvVeldhuizen, NTS 8, 1925, 129–33; 10, 1927, 42–44; HWindisch, ZNW 26, 1927, 203–9; JGnilka, Die Verstockung Israels ’61, 45–48; B-D-F §369, 2 [aqui e em B-D-R p. 386f n. 2, a bibliografia sobre o valor «causal» de <span class=\"greek\">ἵνα</span>, admitido ao menos para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:14</a> and talvez 14:13, onde P47 apresenta <span class=\"greek\">ὅτι</span>; ver 2g]. Ver também FLaCava, Scuola Cattol. 65, ’37, 301–4; MBlack, An Aramaic Approach3, ’67, 211–16; ISluiter, Causal <span class=\"greek\">ἵνα</span>, Sound Greek: Glotta 70, ’92, 39–53. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:7</a> ver <span class=\"greek\">τηρέω</span> 2a).</p><p class=\"entry-text\">④ partícula que confere ênfase retroativa, «que». Às vezes, contrariamente ao uso habitual, <span class=\"greek\">ἵνα</span> é colocado em posição diferente da inicial de sua oração para dar ênfase às palavras que o precedem (B-D-F §475, 1; cf. a posição de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:11</a>): <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">γνῶτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:4</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐρχόμενον</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">πιστεύσωσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:4</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑμετέρῳ</span> <span class=\"greek\">ἐλέει</span> <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:31</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:16b</a>.—EStauffer, <span class=\"greek\">Ἵνα</span> u. d. Problem d. teleol. Denkens b. Pls: StKr 102, 1930, 232–57; JGreenlee, <span class=\"greek\">ἵνα</span> Substantive Clauses in the NT: Asbury Seminarian 2, ’47, 154–63; HRiesenfeld, Zu d. johanneischen <span class=\"greek\">ἵνα</span>-Sätzen, StTh 19, ’65, 213–20; MBlack, An Aramaic Approach3, ’67, 76–81.—Frisk. M-M. EDNT. TW.</p></section></article>\n"};
